parameters.jsCode:
const body = $input.item.json.body || $input.item.json;
const messageData = body.data || body;

// Ignorar mensagens enviadas pelo próprio bot
if (messageData.key?.fromMe === true) {
  return null;
}

// Ignorar mensagens de grupos do WhatsApp (@g.us)
const rawRemoteJid = messageData.key?.remoteJid || messageData.sender || '';
if (rawRemoteJid.includes('@g.us') || messageData.key?.participant) {
  return null;
}

// Extrair número do remetente
let sender = rawRemoteJid.replace('@s.whatsapp.net', '').replace('@c.us', '');
if (sender.includes('@g.us') || sender.includes('-') || sender.length > 15) {
  return null;
}

// Identificar tipo de mídia e conteúdo
let messageType = messageData.messageType || 'conversation';
let tipoMidia = 'texto';
let textContent = '';
let base64Media = null;

if (messageData.message?.audioMessage || messageType === 'audioMessage') {
  tipoMidia = 'audio';
  base64Media = messageData.message?.audioMessage?.base64 || messageData.base64 || null;
  textContent = '[Áudio WhatsApp]';
} else if (messageData.message?.imageMessage || messageType === 'imageMessage') {
  tipoMidia = 'imagem';
  base64Media = messageData.message?.imageMessage?.base64 || messageData.base64 || null;
  textContent = messageData.message?.imageMessage?.caption || '';
} else if (messageData.message?.conversation) {
  tipoMidia = 'texto';
  textContent = messageData.message.conversation;
} else if (messageData.message?.extendedTextMessage?.text) {
  tipoMidia = 'texto';
  textContent = messageData.message.extendedTextMessage.text;
} else {
  return null;
}

return {
  sender,
  tipo_midia: tipoMidia,
  mensagem: textContent,
  media_base64: base64Media,
  message_data: messageData,
  pushName: messageData.pushName || 'Usuário',
  instance: body.instance || 'empresa_1'
};

